(1190714, 149533, 30841, '<td valign="top">great lighting, would have maybe brought the subject more to the right to fill in the gap there, nothing cropping wouldn''t address. without the title, I wouldn''t tie in the theme. 5</td>', 'great lighting, would have maybe brought the subject more to the right to fill in the gap there, nothing cropping wouldn''t address. without the title, I wouldn''t tie in the theme. 5', '2005-02-23 12:35:04.000000', NULL, 1),
