(1190720, 149597, 33736, '<td valign="top">Huh? I would have liked the light positioned directly behind the pursuer. As it stands, it lessens the impact of the title subject. Foreground angle and coloring are wonderful.</td>', 'Huh? I would have liked the light positioned directly behind the pursuer. As it stands, it lessens the impact of the title subject. Foreground angle and coloring are wonderful.', '2005-02-23 12:37:01.000000', NULL, 1),
(1190721, 149217, 30841, '<td valign="top">love the composition. The hair is a bit smudgy from I suspect shutter speed, but that is probably the effect you were looking for. Really fills out the entire frame. Good job. 9</td>', 'love the composition. The hair is a bit smudgy from I suspect shutter speed, but that is probably the effect you were looking for. Really fills out the entire frame. Good job. 9', '2005-02-23 12:37:03.000000', NULL, 1),
