(1190723, 149516, 9452, '<td valign="top">Oh my! Are you sure you shot this pic on this week? I mean, even the shoes are in the old fashion (including the coach)! 10 from me.</td>', 'Oh my! Are you sure you shot this pic on this week? I mean, even the shoes are in the old fashion (including the coach)! 10 from me.', '2005-02-23 12:37:49.000000', NULL, 1),
(1190725, 147834, 30841, '<td valign="top">great color in the sky. the title has to tie it in with the theme, but that''s ok. If you were going for a war theme, I would have left out the sail boat. Anyhow great job, 8</td>', 'great color in the sky. the title has to tie it in with the theme, but that''s ok. If you were going for a war theme, I would have left out the sail boat. Anyhow great job, 8', '2005-02-23 12:38:40.000000', NULL, 1),
(1190728, 149600, 33736, '<td valign="top">I wondered why your title wasn''t "out of" instead of "into the past", until a second look at the road sign (too dark) showed that he was headed for Canada (instead of Vietnam?)</td>', 'I wondered why your title wasn''t "out of" instead of "into the past", until a second look at the road sign (too dark) showed that he was headed for Canada (instead of Vietnam?)', '2005-02-23 12:39:21.000000', NULL, 1),
