(1190753, 149373, 30841, '<td valign="top">I imagine the lens was intended to be out of focus, but it shouldn''t be because it is the majority of the shot. Everything else is really great, the placement of everything is perfect. 6</td>', 'I imagine the lens was intended to be out of focus, but it shouldn''t be because it is the majority of the shot. Everything else is really great, the placement of everything is perfect. 6', '2005-02-23 12:47:06.000000', NULL, 1),
(1190754, 149246, 30841, '<td valign="top">just not a fan 4</td>', 'just not a fan 4', '2005-02-23 12:47:43.000000', NULL, 1),
(1190756, 149533, 2612, '<td valign="top">The introduction of Robin Williams was definitely one of the high points of the 70''s. Not a lot of wow factor in the photograph but I like the fact that is has documentary significance.</td>', 'The introduction of Robin Williams was definitely one of the high points of the 70''s. Not a lot of wow factor in the photograph but I like the fact that is has documentary significance.', '2005-02-23 12:49:01.000000', NULL, 1),
