(1190787, 149556, 33736, '<td valign="top">You caught the dignified tastes of the 70''s perfectly. Including the chest hairs in as part of the display rounded out the reality of that era.  Your composition, focus, lighting, and cropping are top of the line.</td>', 'You caught the dignified tastes of the 70''s perfectly. Including the chest hairs in as part of the display rounded out the reality of that era.  Your composition, focus, lighting, and cropping are top of the line.', '2005-02-23 12:59:34.000000', NULL, 1),
(1190788, 149313, 30841, '<td valign="top">superb color and lighting! 10</td>', 'superb color and lighting! 10', '2005-02-23 12:59:39.000000', NULL, 1),
