(1192336, 149542, 33560, '<td valign="top">My, but isn''t this godawful ugly!  Even knowing that this was the photographer''s intent it''s hard to give this a really high score.</td>', 'My, but isn''t this godawful ugly!  Even knowing that this was the photographer''s intent it''s hard to give this a really high score.', '2005-02-24 08:33:23.000000', NULL, 1),
(1192338, 149019, 33560, '<td valign="top">Highly evocative.  Nice job.</td>', 'Highly evocative.  Nice job.', '2005-02-24 08:34:12.000000', NULL, 1),
(1192339, 149365, 27524, '<td valign="top">:) yeah... some still treasure them... nice colors and lights...</td>', ':) yeah... some still treasure them... nice colors and lights...', '2005-02-24 08:35:33.000000', NULL, 1),
(1192340, 148562, 27524, '<td valign="top">Thats horror...uhh...</td>', 'Thats horror...uhh...', '2005-02-24 08:36:18.000000', NULL, 1),
(1192341, 149186, 33560, '<td valign="top">A path not much travelled in this competition.  I love the way the colors and textures of the roof, chimney, and walls play off each other.  I love the rhythm created by all the repeated elements.  The photo communicates age  and speaks of an unadorned and utilitarian time.</td>', 'A path not much travelled in this competition.  I love the way the colors and textures of the roof, chimney, and walls play off each other.  I love the rhythm created by all the repeated elements.  The photo communicates age  and speaks of an unadorned and utilitarian time.', '2005-02-24 08:36:48.000000', NULL, 1),
(1192345, 149344, 27524, '<td valign="top">Pritty interesting one... just bit dont like heavy contrast between gras and leather.</td>', 'Pritty interesting one... just bit dont like heavy contrast between gras and leather.', '2005-02-24 08:38:29.000000', NULL, 1),
(1192346, 149516, 33560, '<td valign="top">Droll. And highly evocative.  Great job.</td>', 'Droll. And highly evocative.  Great job.', '2005-02-24 08:39:11.000000', NULL, 1),
(1192348, 149553, 27524, '<td valign="top">One of moust artistic ideas... nice done...</td>', 'One of moust artistic ideas... nice done...', '2005-02-24 08:39:31.000000', NULL, 1),
(1192349, 148244, 27524, '<td valign="top">wow... look pretty realistic...</td>', 'wow... look pretty realistic...', '2005-02-24 08:41:09.000000', NULL, 1),
(1192350, 149197, 33560, '<td valign="top">Great idea.  Tell us, did you destroy this map to make the photo, or was there an intervening surface?</td>', 'Great idea.  Tell us, did you destroy this map to make the photo, or was there an intervening surface?', '2005-02-24 08:41:30.000000', NULL, 1),
(1192354, 147859, 33560, '<td valign="top">The contrast seems too low throughout the photo.  Perhaps it is meant to look faded, but somehow it fails to communicate this.</td>', 'The contrast seems too low throughout the photo.  Perhaps it is meant to look faded, but somehow it fails to communicate this.', '2005-02-24 08:45:33.000000', NULL, 1),
(1192357, 149212, 33560, '<td valign="top">While this photo clearly shows how badly the photographic print from that era looked and lasted, and while it shows us what people did and how they dressed, to me it looks muddled, jumbled, and just too hard to make out.</td>', 'While this photo clearly shows how badly the photographic print from that era looked and lasted, and while it shows us what people did and how they dressed, to me it looks muddled, jumbled, and just too hard to make out.', '2005-02-24 08:49:01.000000', NULL, 1),
(1192361, 149268, 164, '<td valign="top">Nice picture 70''s?</td>', 'Nice picture 70''s?', '2005-02-24 08:50:51.000000', NULL, 1),
(1192363, 148542, 33560, '<td valign="top">This photo manages to capture so much that was ugly in the seventies and is ugly today:  even though my reaction is strongly negative, I''ve got to nudge this up a bit.</td>', 'This photo manages to capture so much that was ugly in the seventies and is ugly today:  even though my reaction is strongly negative, I''ve got to nudge this up a bit.', '2005-02-24 08:52:37.000000', NULL, 1),
(1192364, 149230, 164, '<td valign="top">What we won''t make our kids do, :)</td>', 'What we won''t make our kids do, :)', '2005-02-24 08:52:56.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1192370, 149234, 33535, '<td valign="top">cool shadows, but alittlebit too much grey<br/>how did you do that ;-)</td>', 'cool shadows, but alittlebit too much greyhow did you do that ;-)', '2005-02-24 08:55:48.000000', NULL, 1),
(1192373, 149466, 33560, '<td valign="top">What bothered me first about the photo was it''s smudgy quality, and I rated it very low for that. But   this photo makes a great use of negative space.  And the lines created by the broken sticks are perfectly composed.  Finally, I love the simple but compelling color palette.</td>', 'What bothered me first about the photo was it''s smudgy quality, and I rated it very low for that. But   this photo makes a great use of negative space.  And the lines created by the broken sticks are perfectly composed.  Finally, I love the simple but compelling color palette.', '2005-02-24 08:57:23.000000', NULL, 1),
(1192375, 149259, 33535, '<td valign="top">nice reflections on the rings cool idea<br/>only the background is boring ( could have been better with red for example)</td>', 'nice reflections on the rings cool ideaonly the background is boring ( could have been better with red for example)', '2005-02-24 08:58:54.000000', NULL, 1),
(1192378, 149512, 33560, '<td valign="top">It seems out of focus to me.  And the color palette seems to wierd, even by seventies standards. I find the lighting harsh and strangely colored .Also not purposefully trippy.  The wilted rose stem detracts much.</td>', 'It seems out of focus to me.  And the color palette seems to wierd, even by seventies standards. I find the lighting harsh and strangely colored .Also not purposefully trippy.  The wilted rose stem detracts much.', '2005-02-24 09:00:23.000000', NULL, 1),
(1192382, 149462, 33560, '<td valign="top">I have to assume the oversaturation is purposeful.  But not being able to see the rest of the grooves in the record is a problem, especially since this negative space is a wierd and ugly greenish color.</td>', 'I have to assume the oversaturation is purposeful.  But not being able to see the rest of the grooves in the record is a problem, especially since this negative space is a wierd and ugly greenish color.', '2005-02-24 09:03:16.000000', NULL, 1),
(1192384, 148562, 33560, '<td valign="top">I''m afraid I suffer from a handicap in scoring this - never have seen a slasher movie.  Although it needs to be dark and shadowy for effect, I found this to be too hard to see.</td>', 'I''m afraid I suffer from a handicap in scoring this - never have seen a slasher movie.  Although it needs to be dark and shadowy for effect, I found this to be too hard to see.', '2005-02-24 09:05:15.000000', NULL, 1),
(1192388, 149574, 33560, '<td valign="top">This just does not look like a ''seventies guy.''   Really, to evoke the seventies, facial hair on men is a must.  Sideburns or a beard or an unstylish moustache are a minimum.   I''m afraid I can''t stand the colorful effects, no matter how much (or little) effort it might have taken to produce them.</td>', 'This just does not look like a ''seventies guy.''   Really, to evoke the seventies, facial hair on men is a must.  Sideburns or a beard or an unstylish moustache are a minimum.   I''m afraid I can''t stand the colorful effects, no matter how much (or little) effort it might have taken to produce them.', '2005-02-24 09:09:36.000000', NULL, 1),
