INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1195841, 149378, 30441, '<td valign="top">I like the composition and color. I wonder if the photo was taken a bit further back to see more of the label would be even better. I want to see more of the image.</td>', 'I like the composition and color. I wonder if the photo was taken a bit further back to see more of the label would be even better. I want to see more of the image.', '2005-02-26 14:45:31.000000', NULL, 1),
(1195844, 149258, 30441, '<td valign="top">As an abstract it is a very interesting and well done image. Not sure about the match to the theme though.</td>', 'As an abstract it is a very interesting and well done image. Not sure about the match to the theme though.', '2005-02-26 14:47:16.000000', NULL, 1),
(1195845, 149257, 33947, '<td valign="top">Nice representation of theme.</td>', 'Nice representation of theme.', '2005-02-26 14:47:18.000000', NULL, 1),
