(1195849, 149517, 30441, '<td valign="top">Nice documentary feel, as if actually taken in the 70''s.</td>', 'Nice documentary feel, as if actually taken in the 70''s.', '2005-02-26 14:49:54.000000', NULL, 1),
(1195852, 147906, 33947, '<td valign="top">I like the soft focus and the lighting, but part of the image is hard to make out.</td>', 'I like the soft focus and the lighting, but part of the image is hard to make out.', '2005-02-26 14:51:09.000000', NULL, 1),
(1195853, 148714, 33947, '<td valign="top">Good theme idea, and I like the execution.</td>', 'Good theme idea, and I like the execution.', '2005-02-26 14:52:03.000000', NULL, 1),
(1195856, 149050, 33947, '<td valign="top">Excellent portrayal of the ''70''s, and interesting and unique execution.</td>', 'Excellent portrayal of the ''70''s, and interesting and unique execution.', '2005-02-26 14:54:02.000000', NULL, 1),
(1195857, 149259, 30441, '<td valign="top">I wish the background had been either white or black for more contrast. Nice focus and getting the engraving in the right spot.</td>', 'I wish the background had been either white or black for more contrast. Nice focus and getting the engraving in the right spot.', '2005-02-26 14:54:29.000000', NULL, 1),
(1195862, 147836, 33947, '<td valign="top">Good theme idea.</td>', 'Good theme idea.', '2005-02-26 14:56:55.000000', NULL, 1),
(1195863, 148584, 30441, '<td valign="top">I''d like to see more of the object.</td>', 'I''d like to see more of the object.', '2005-02-26 14:57:12.000000', NULL, 1),
(1195865, 149258, 33081, '<td valign="top">While this photo does have an old feel to it, I''m missing the connection to the 1970''s.  The orange figure in the background reminds me of the cingular wireless logo, lol</td>', 'While this photo does have an old feel to it, I''m missing the connection to the 1970''s.  The orange figure in the background reminds me of the cingular wireless logo, lol', '2005-02-26 14:57:57.000000', NULL, 1),
(1195866, 149586, 30441, '<td valign="top">I think the attempt was good, but the focus seems off to me. I wonder if a color image would have worked well to help identify the clothes as last season.</td>', 'I think the attempt was good, but the focus seems off to me. I wonder if a color image would have worked well to help identify the clothes as last season.', '2005-02-26 14:58:25.000000', NULL, 1),
(1195870, 148244, 33947, '<td valign="top">LIke the way the helmut is lit, and like the black background.</td>', 'LIke the way the helmut is lit, and like the black background.', '2005-02-26 15:00:07.000000', NULL, 1),
(1195871, 149233, 30441, '<td valign="top">You get points for humor but I have to mention that Yoda wasn''t introduced until the 80''s.</td>', 'You get points for humor but I have to mention that Yoda wasn''t introduced until the 80''s.', '2005-02-26 15:00:16.000000', NULL, 1),
(1195872, 147836, 33081, '<td valign="top">This appears to be a snapshot, rather than an attempt at photography.  The people in the photo don''t look very "retro", but I wouldn''t expect them too, unless this was a planned photo shoot.</td>', 'This appears to be a snapshot, rather than an attempt at photography.  The people in the photo don''t look very "retro", but I wouldn''t expect them too, unless this was a planned photo shoot.', '2005-02-26 15:00:32.000000', NULL, 1),
(1195873, 149547, 33081, '<td valign="top">Nice idea.  Photo seems a bit too dark, and the subject appears to be moving.</td>', 'Nice idea.  Photo seems a bit too dark, and the subject appears to be moving.', '2005-02-26 15:01:28.000000', NULL, 1),
(1195877, 148490, 33947, '<td valign="top">Nice composition. Like how my eye goes from the guitar, to the lava lamp and to the beads in her hair. Excellent theme picture.</td>', 'Nice composition. Like how my eye goes from the guitar, to the lava lamp and to the beads in her hair. Excellent theme picture.', '2005-02-26 15:03:17.000000', NULL, 1),
(1195878, 149507, 33081, '<td valign="top">okay, now I get it...missed the title first time around.  that''s thinking outside the box, haha...</td>', 'okay, now I get it...missed the title first time around.  that''s thinking outside the box, haha...', '2005-02-26 15:03:40.000000', NULL, 1),
(1195879, 149259, 33081, '<td valign="top">This would have looked more appealing with a more white background, but for the "70''s" theme, the background is perfect.  Nice job!</td>', 'This would have looked more appealing with a more white background, but for the "70''s" theme, the background is perfect.  Nice job!', '2005-02-26 15:05:07.000000', NULL, 1),
(1195882, 149553, 33947, '<td valign="top">I love it. Great background, and great tiny balls that have the feeling of bubbles. Excellent theme photo. Nice use of repetition and color.</td>', 'I love it. Great background, and great tiny balls that have the feeling of bubbles. Excellent theme photo. Nice use of repetition and color.', '2005-02-26 15:09:58.000000', NULL, 1),
(1195884, 149457, 30441, '<td valign="top">Definitely looks like it was taken during the 70''s. Good expression on the model.</td>', 'Definitely looks like it was taken during the 70''s. Good expression on the model.', '2005-02-26 15:10:50.000000', NULL, 1),
(1195886, 149241, 33947, '<td valign="top">Great theme idea. Liked the way you zoomed in and cropped it. Also like the blurry background.</td>', 'Great theme idea. Liked the way you zoomed in and cropped it. Also like the blurry background.', '2005-02-26 15:12:42.000000', NULL, 1),
