(1202542, 149516, 16266, '<td valign="top">congrats on a great image.<br/> <br/>This one, by far, stood out from all the other images for me.  Great image, and I am glad i ribboned.</td>', 'congrats on a great image. This one, by far, stood out from all the other images for me.  Great image, and I am glad i ribboned.', '2005-03-02 03:00:18.000000', NULL, 0),
(1202578, 149173, 27137, '<td valign="top">Great idea, a profile from the 70s, which is not clishe, and more abstract to capture<br/>The 70 where much more than hippies and drugs and this photograph honours those people who where actively involved in making a difference<br/> <br/>Congrats!<br/></td>', 'Great idea, a profile from the 70s, which is not clishe, and more abstract to captureThe 70 where much more than hippies and drugs and this photograph honours those people who where actively involved in making a difference Congrats!', '2005-03-02 03:26:31.000000', NULL, 0),
(1202586, 149553, 31637, '<td valign="top">Congratulations on your first blue ribbon. Must be a good feeling, all your hard work paid off. I was one of your 10''s Great job !</td>', 'Congratulations on your first blue ribbon. Must be a good feeling, all your hard work paid off. I was one of your 10''s Great job !', '2005-03-02 03:35:21.000000', NULL, 0),
